   334  static int igraph_i_gml_convert_to_key(const char *orig, char **key) {
   335      int no = 1;
   336      char strno[50];
   337      size_t i, len = strlen(orig), newlen = 0, plen = 0;
   338
   339      /* do we need a prefix? */
   340      if (len == 0 || !isalpha(orig[0])) {
   341          no++;
   342          snprintf(strno, sizeof(strno) - 1, "igraph");
   343          plen = newlen = strlen(strno);
   344      }
   345      for (i = 0; i < len; i++) {
   346          if (isalnum(orig[i])) {
   347              newlen++;
   348          }
   349      }
   350      *key = igraph_Calloc(newlen + 1, char);
   351      if (! *key) {
   352          IGRAPH_ERROR("Writing GML file failed", IGRAPH_ENOMEM);
   353      }
   354      memcpy(*key, strno, plen * sizeof(char));
   355      for (i = 0; i < len; i++) {
   356          if (isalnum(orig[i])) {
   357              (*key)[plen++] = orig[i];
   358          }
   359      }
   360      (*key)[newlen] = '\0';
