    43  static void igraph_i_gml_destroy_attrs(igraph_vector_ptr_t **ptr) {
    44      long int i;
    45      igraph_vector_ptr_t *vec;
    46      for (i = 0; i < 3; i++) {
    47          long int j;
    48          vec = ptr[i];
    49          for (j = 0; j < igraph_vector_ptr_size(vec); j++) {
    50              igraph_attribute_record_t *atrec = VECTOR(*vec)[j];
    51              if (atrec->type == IGRAPH_ATTRIBUTE_NUMERIC) {
    52                  igraph_vector_t *value = (igraph_vector_t*)atrec->value;
    53                  if (value != 0) {
    54                      igraph_vector_destroy(value);
    55                      igraph_Free(value);
    56                  }
    57              } else {
    58                  igraph_strvector_t *value = (igraph_strvector_t*)atrec->value;
    59                  if (value != 0) {
    60                      igraph_strvector_destroy(value);
    61                      igraph_Free(value);
    62                  }
    63              }
    64              igraph_Free(atrec->name);
    65              igraph_Free(atrec);
    66          }
    67          igraph_vector_ptr_destroy(vec);
    68      }
    69  }
