    71  static igraph_real_t igraph_i_gml_toreal(igraph_gml_tree_t *node, long int pos) {
    72
    73      igraph_real_t value = 0.0;
    74      int type = igraph_gml_tree_type(node, pos);
    75
    76      switch (type) {
    77      case IGRAPH_I_GML_TREE_INTEGER:
    78          value = igraph_gml_tree_get_integer(node, pos);
    79          break;
    80      case IGRAPH_I_GML_TREE_REAL:
    81          value = igraph_gml_tree_get_real(node, pos);
    82          break;
    83      default:
    84          IGRAPH_ERROR("Internal error while parsing GML file", IGRAPH_FAILURE);
    85          break;
    86      }
    87
    88      return value;
    89  }
