    91  static const char *igraph_i_gml_tostring(igraph_gml_tree_t *node, long int pos) {
    92
    93      int type = igraph_gml_tree_type(node, pos);
    94      static char tmp[256];
    95      const char *p = tmp;
    96      long int i;
    97      igraph_real_t d;
    98
    99      switch (type) {
   100      case IGRAPH_I_GML_TREE_INTEGER:
   101          i = igraph_gml_tree_get_integer(node, pos);
   102          snprintf(tmp, sizeof(tmp) / sizeof(char), "%li", i);
   103          break;
   104      case IGRAPH_I_GML_TREE_REAL:
   105          d = igraph_gml_tree_get_real(node, pos);
   106          igraph_real_snprintf_precise(tmp, sizeof(tmp) / sizeof(char), d);
   107          break;
   108      case IGRAPH_I_GML_TREE_STRING:
   109          p = igraph_gml_tree_get_string(node, pos);
   110          break;
   111      default:
   112          break;
   113      }
   114
   115      return p;
