   118  /**
   119   * \function igraph_read_graph_gml
   120   * \brief Read a graph in GML format.
   121   *
   122   * GML is a simple textual format, see
   123   * http://www.fim.uni-passau.de/en/fim/faculty/chairs/theoretische-informatik/projects.html for details.
   124   *
   125   * </para><para>
   126   * Although all syntactically correct GML can be parsed,
   127   * we implement only a subset of this format, some attributes might be
   128   * ignored. Here is a list of all the differences:
   129   * \olist
   130   * \oli Only <code>node</code> and <code>edge</code> attributes are
   131   *      used, and only if they have a simple type: integer, real or
   132   *      string. So if an attribute is an array or a record, then it is
   133   *      ignored. This is also true if only some values of the
   134   *      attribute are complex.
   135   * \oli Top level attributes except for <code>Version</code> and the
   136   *      first <code>graph</code> attribute are completely ignored.
   137   * \oli Graph attributes except for <code>node</code> and
   138   *      <code>edge</code> are completely ignored.
   139   * \oli There is no maximum line length.
   140   * \oli There is no maximum keyword length.
   141   * \oli Character entities in strings are not interpreted.
   142   * \oli We allow <code>inf</code> (infinity) and <code>nan</code>
   143   *      (not a number) as a real number. This is case insensitive, so
   144   *      <code>nan</code>, <code>NaN</code> and <code>NAN</code> are equal.
   145   * \endolist
   146   *
   147   * </para><para> Please contact us if you cannot live with these
   148   * limitations of the GML parser.
   149   * \param graph Pointer to an uninitialized graph object.
   150   * \param instream The stream to read the GML file from.
   151   * \return Error code.
   152   *
   153   * Time complexity: should be proportional to the length of the file.
   154   *
   155   * \sa \ref igraph_read_graph_graphml() for a more modern format,
   156   * \ref igraph_write_graph_gml() for writing GML files.
   157   *
   158   * \example examples/simple/gml.c
   159   */
   160  int igraph_read_graph_gml(igraph_t *graph, FILE *instream) {
   161
   162      long int i, p;
   163      long int no_of_nodes = 0, no_of_edges = 0;
   164      igraph_trie_t trie;
   165      igraph_vector_t edges;
   166      igraph_bool_t directed = IGRAPH_UNDIRECTED;
   167      igraph_gml_tree_t *gtree;
   168      long int gidx;
   169      igraph_trie_t vattrnames;
   170      igraph_trie_t eattrnames;
   171      igraph_trie_t gattrnames;
   172      igraph_vector_ptr_t gattrs = IGRAPH_VECTOR_PTR_NULL,
   173                          vattrs = IGRAPH_VECTOR_PTR_NULL, eattrs = IGRAPH_VECTOR_PTR_NULL;
   174      igraph_vector_ptr_t *attrs[3];
   175      long int edgeptr = 0;
   176      igraph_i_gml_parsedata_t context;
   177
   178      attrs[0] = &gattrs; attrs[1] = &vattrs; attrs[2] = &eattrs;
   179
   180      context.eof = 0;
   181      context.tree = 0;
   182
   183      igraph_gml_yylex_init_extra(&context, &context.scanner);
   184      IGRAPH_FINALLY(igraph_gml_yylex_destroy, context.scanner);
   185
   186      igraph_gml_yyset_in(instream, context.scanner);
   187
   188      i = igraph_gml_yyparse(&context);
   189      if (i != 0) {
   190          if (context.errmsg[0] != 0) {
   191              IGRAPH_ERROR(context.errmsg, IGRAPH_PARSEERROR);
   192          } else {
   193              IGRAPH_ERROR("Cannot read GML file", IGRAPH_PARSEERROR);
   194          }
   195      }
   196
   197      IGRAPH_VECTOR_INIT_FINALLY(&edges, 0);
   198
   199      /* Check version, if present, integer and not '1' then ignored */
   200      i = igraph_gml_tree_find(context.tree, "Version", 0);
   201      if (i >= 0 &&
   202          igraph_gml_tree_type(context.tree, i) == IGRAPH_I_GML_TREE_INTEGER &&
   203          igraph_gml_tree_get_integer(context.tree, i) != 1) {
   204          igraph_gml_tree_destroy(context.tree);
