   207      }
   208
   209      /* get the graph */
   210      gidx = igraph_gml_tree_find(context.tree, "graph", 0);
   211      if (gidx == -1) {
   212          IGRAPH_ERROR("No 'graph' object in GML file", IGRAPH_PARSEERROR);
   213      }
   214      if (igraph_gml_tree_type(context.tree, gidx) !=
   215          IGRAPH_I_GML_TREE_TREE) {
   216          IGRAPH_ERROR("Invalid type for 'graph' object in GML file", IGRAPH_PARSEERROR);
   217      }
   218      gtree = igraph_gml_tree_get_tree(context.tree, gidx);
   219
   220      IGRAPH_FINALLY(igraph_i_gml_destroy_attrs, attrs);

